sql.where:
AND o.order_status NOT IN ('CANCELED','SHIPPED')



    AND (o.order_no      ILIKE '%' || #{keyword} || '%'
      OR o.ext_order_no  ILIKE '%' || #{keyword} || '%'
      OR o.receiver_name ILIKE '%' || #{keyword} || '%')


    AND ch.channel_id = #{channelId}


    AND al.plant_id = #{plantId}



    AND al.alloc_line_count = 1 AND al.alloc_qty = 1


    AND NOT (al.alloc_line_count = 1 AND al.alloc_qty = 1)






            AND o.created_by = #{scope.ownerId}


            AND ( al.org_seq IN

                      #{org}

                  OR o.created_by = #{scope.ownerId} )

mapper.select:
SELECT o.order_seq AS orderSeq, o.order_no AS orderNo, ch.channel_id AS channelId, ch.channel_name AS channelName, o.ext_order_no AS extOrderNo, o.ordered_at AS orderedAt, o.receiver_name AS receiverName, o.address AS address, al.plant_id AS plantId, al.plant_name AS plantName, al.alloc_line_count::int AS lineCount, (SELECT COALESCE(SUM(l3.order_qty), 0) FROM tb_order_line l3 WHERE l3.order_seq = o.order_seq AND l3.line_status <> 'CANCELED')::int AS totalQty, al.alloc_qty::int AS allocatedQty, (al.alloc_line_count = 1 AND al.alloc_qty = 1) AS singlePack, (al.plant_count > 1) AS multiPlant
ORDER BY o.ordered_at, o.order_seq
LIMIT #{size} OFFSET #{offset}

SELECT 



 ORDER BY ${sortColumn} ${sortDirection}, o.outbound_seq DESC

    LIMIT #{size} OFFSET #{offset}
